import ast, sys

for path in ["src/attr/_funcs.py", "src/attr/_make.py"]:
    src = open(path).read()
    tree = ast.parse(src)
    lines = [i+1 for i, l in enumerate(src.splitlines()) if "_OBJ_SETATTR" in l]
    # build stack mapping
    results = {}
    def walk(node, stack):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                new = stack + [child.name]
                for ln in lines:
                    if child.lineno <= ln <= child.end_lineno:
                        prev = results.get(ln)
                        if prev is None or len(new) > len(prev):
                            results[ln] = new
                walk(child, new)
            else:
                walk(child, stack)
    walk(tree, [])
    for ln in lines:
        print(path, ln, ".".join(results.get(ln, ["<module>"])), "|", src.splitlines()[ln-1].strip())
EOF

